public class ConcurrentGraphTraversal {

    private static final AtomicInteger completedThreads = new AtomicInteger(0);
    private static final AtomicInteger numVertices = new AtomicInteger(0);
    private static final AtomicInteger numEdges = new AtomicInteger(0);

    static class Graph {
        private final Map<Integer, List<Integer>> adjList = new HashMap<>();

        public void addVertex(int v) {
            adjList.putIfAbsent(v, new ArrayList<>());
            numVertices.incrementAndGet();
        }

        public void addEdge(int src, int dest) {
            adjList.computeIfAbsent(src, k -> new ArrayList<>()).add(dest);
            numEdges.incrementAndGet();
        }

        public List<Integer> getNeighbors(int v) {
            return adjList.getOrDefault(v, Collections.emptyList());
        }
    }

    static class TraversalThread extends Thread {
        private final Graph graph;
        private final int startVertex;
        private final Set<Integer> visited;

        public TraversalThread(Graph graph, int startVertex, Set<Integer> visited) {
            this.graph = graph;
            this.startVertex = startVertex;
            this.visited = visited;
        }

        @Override
        public void run() {
            Queue<Integer> queue = new LinkedList<>();
            if (visited.add(startVertex)) {
                queue.add(startVertex);
            }

            while (!queue.isEmpty()) {
                int vertex = queue.poll();
                for (int neighbor : graph.getNeighbors(vertex)) {
                    if (visited.add(neighbor)) {
                        queue.add(neighbor);
                    }
                }
            }
            completedThreads.incrementAndGet();
        }
    }

    public static void main(String[] args) {
        Graph graph = new Graph();

        for (int i = 0; i < 10; i++) {
            graph.addVertex(i);
        }

