        public int find(int i) {
            if (!parent.containsKey(i)) {
                return i;
            }
            if (parent.get(i) != i) {
                parent.put(i, find(parent.get(i)));
            }
            return parent.get(i);
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                int rankI = rank.get(rootI);
                int rankJ = rank.get(rootJ);
                if (rankI < rankJ) {
                    parent.put(rootI, rootJ);
                } else if (rankI > rankJ) {
                    parent.put(rootJ, rootI);
                } else {
                    parent.put(rootJ, rootI);
                    rank.put(rootI, rankI + 1);
                }
            }
        }
    }

    public static int countDisjointPairs(int[] arr) {
        if (arr == null || arr.length < 2) {
            return 0;
        }

        UnionFind uf = new UnionFind(arr);
        int disjointPairsCount = 0;

        for (int i = 0; i < arr.length; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                long startTime = System.currentTimeMillis();

                boolean isDisjoint = (uf.find(arr[i]) != uf.find(arr[j]));

                long endTime = System.currentTimeMillis();
                System.out.println("Time taken to check pair (" + arr[i] + ", " + arr[j] + "): " + (endTime - startTime) + " milliseconds");

                if (isDisjoint) {
                    disjointPairsCount++;
                }
            }
        }

        return disjointPairsCount;
    }
